import os
import pytest

from subject import check_critical_env_vars, ModelEnvHealthResult, CRITICAL_ENV_VARS


def _save_and_clear_env():
    """Save current critical env vars and remove them from os.environ."""
    saved = {}
    for var, _ in CRITICAL_ENV_VARS:
        saved[var] = os.environ.get(var)
        os.environ.pop(var, None)
    return saved


def _restore_env(saved):
    """Restore critical env vars from saved dict."""
    for var, val in saved.items():
        if val is None:
            os.environ.pop(var, None)
        else:
            os.environ[var] = val


@pytest.mark.unit
def test_check_critical_env_vars_all_set():
    saved = _save_and_clear_env()
    try:
        os.environ["INTELLIGENCE_SERVICE_URL"] = "http://example.com"
        os.environ["KAFKA_BOOTSTRAP_SERVERS"] = "localhost:9092"
        result = check_critical_env_vars()
        assert result.healthy is True
        assert result.warnings == []
    finally:
        _restore_env(saved)


@pytest.mark.unit
def test_check_critical_env_vars_one_missing():
    saved = _save_and_clear_env()
    try:
        os.environ["INTELLIGENCE_SERVICE_URL"] = "http://example.com"
        # KAFKA_BOOTSTRAP_SERVERS not set
        result = check_critical_env_vars()
        assert result.healthy is False
        assert len(result.warnings) == 1
        warning = result.warnings[0]
        assert "KAFKA_BOOTSTRAP_SERVERS" in warning
        assert "Impact:" in warning
        # Verify exact impact description
        _, expected_impact = next(v for v in CRITICAL_ENV_VARS if v[0] == "KAFKA_BOOTSTRAP_SERVERS")
        assert expected_impact in warning
    finally:
        _restore_env(saved)


